INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ヒヨリ", 4, "", "vo_empress_100101_001", 1, "", 1, 100101, 5, "vo_empress_100101_001", 0, "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ヒヨリ", 4, "", "vo_empress_100101_002", 2, "", 1, 100103, 5, "vo_empress_100101_002", 0, "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ヒヨリ", 4, "", "vo_empress_100101_003", 3, "", 1, 100103, 5, "vo_empress_100101_003", 0, "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ヒヨリ", 4, "", "vo_empress_100101_004", 4, "", 1, 100102, 5, "vo_empress_100101_004", 100101, "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ユイ", 4, "", "vo_empress_100201_001", 5, "", 1, 100203, 5, "vo_empress_100201_001", 0, "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ユイ", 4, "", "vo_empress_100201_002", 6, "", 1, 100203, 5, "vo_empress_100201_002", 0, "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ユイ", 4, "", "vo_empress_100201_003", 7, "", 1, 100203, 5, "vo_empress_100201_003", 0, "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ユイ", 4, "", "vo_empress_100201_004", 8, "", 1, 100202, 5, "vo_empress_100201_004", 100201, "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "レイ", 4, "", "vo_empress_100301_001", 9, "", 1, 100301, 5, "vo_empress_100301_001", 0, "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "レイ", 4, "", "vo_empress_100301_002", 10, "", 1, 100303, 5, "vo_empress_100301_002", 0, "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "レイ", 4, "", "vo_empress_100301_003", 11, "", 1, 100303, 5, "vo_empress_100301_003", 0, "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "レイ", 4, "", "vo_empress_100301_004", 12, "", 1, 100302, 5, "vo_empress_100301_004", 100301, "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミソギ", 4, "", "vo_empress_100401_001", 13, "", 1, 100401, 5, "vo_empress_100401_001", 0, "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミソギ", 4, "", "vo_empress_100401_002", 14, "", 1, 100401, 5, "vo_empress_100401_002", 0, "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ミソギ", 4, "", "vo_empress_100401_003", 15, "", 1, 100403, 5, "vo_empress_100401_003", 0, "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ミソギ", 4, "", "vo_empress_100401_004", 16, "", 1, 100402, 5, "vo_empress_100401_004", 100401, "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "マツリ", 4, "", "vo_empress_100501_001", 17, "", 1, 100501, 5, "vo_empress_100501_001", 0, "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "マツリ", 4, "", "vo_empress_100501_002", 18, "", 1, 100501, 5, "vo_empress_100501_002", 0, "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "マツリ", 4, "", "vo_empress_100501_003", 19, "", 1, 100503, 5, "vo_empress_100501_003", 0, "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "マツリ", 4, "", "vo_empress_100501_004", 20, "", 1, 100502, 5, "vo_empress_100501_004", 100501, "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アカリ", 4, "", "vo_empress_100601_001", 21, "", 1, 100603, 5, "vo_empress_100601_001", 0, "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アカリ", 4, "", "vo_empress_100601_002", 22, "", 1, 100601, 5, "vo_empress_100601_002", 0, "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "アカリ", 4, "", "vo_empress_100601_003", 23, "", 1, 100603, 5, "vo_empress_100601_003", 0, "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "アカリ", 4, "", "vo_empress_100601_004", 24, "", 1, 100602, 5, "vo_empress_100601_004", 100601, "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミヤコ", 4, "", "vo_empress_100701_001", 25, "", 1, 100701, 5, "vo_empress_100701_001", 0, "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミヤコ", 4, "", "vo_empress_100701_002", 26, "", 1, 100702, 5, "vo_empress_100701_002", 0, "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ミヤコ", 4, "", "vo_empress_100701_003", 27, "", 1, 100703, 5, "vo_empress_100701_003", 0, "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ミヤコ", 4, "", "vo_empress_100701_004", 28, "", 1, 100702, 5, "vo_empress_100701_004", 100701, "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ユキ", 4, "", "vo_empress_100801_001", 29, "", 1, 100801, 5, "vo_empress_100801_001", 0, "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ユキ", 4, "", "vo_empress_100801_002", 30, "", 1, 100801, 5, "vo_empress_100801_002", 0, "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ユキ", 4, "", "vo_empress_100801_003", 31, "", 1, 100801, 5, "vo_empress_100801_003", 0, "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ユキ", 4, "", "vo_empress_100801_004", 32, "", 1, 100802, 5, "vo_empress_100801_004", 100801, "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アンナ", 4, "", "vo_empress_100901_001", 33, "", 1, 100901, 5, "vo_empress_100901_001", 0, "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アンナ", 4, "", "vo_empress_100901_002", 34, "", 1, 100903, 5, "vo_empress_100901_002", 0, "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "アンナ", 4, "", "vo_empress_100901_003", 35, "", 1, 100903, 5, "vo_empress_100901_003", 0, "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "アンナ", 4, "", "vo_empress_100901_004", 36, "", 1, 100902, 5, "vo_empress_100901_004", 100901, "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "マホ", 4, "", "vo_empress_101001_001", 37, "", 1, 101001, 5, "vo_empress_101001_001", 0, "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "マホ", 4, "", "vo_empress_101001_002", 38, "", 1, 101001, 5, "vo_empress_101001_002", 0, "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "マホ", 4, "", "vo_empress_101001_003", 39, "", 1, 101003, 5, "vo_empress_101001_003", 0, "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "マホ", 4, "", "vo_empress_101001_004", 40, "", 1, 101002, 5, "vo_empress_101001_004", 101001, "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "リノ", 4, "", "vo_empress_101101_001", 41, "", 1, 101101, 5, "vo_empress_101101_001", 0, "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "リノ", 4, "", "vo_empress_101101_002", 42, "", 1, 101101, 5, "vo_empress_101101_002", 0, "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "リノ", 4, "", "vo_empress_101101_003", 43, "", 1, 101103, 5, "vo_empress_101101_003", 0, "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "リノ", 4, "", "vo_empress_101101_004", 44, "", 1, 101102, 5, "vo_empress_101101_004", 101101, "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ハツネ", 4, "", "vo_empress_101201_001", 45, "", 1, 101201, 5, "vo_empress_101201_001", 0, "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ハツネ", 4, "", "vo_empress_101201_002", 46, "", 1, 101202, 5, "vo_empress_101201_002", 0, "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ハツネ", 4, "", "vo_empress_101201_003", 47, "", 1, 101203, 5, "vo_empress_101201_003", 0, "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ハツネ", 4, "", "vo_empress_101201_004", 48, "", 1, 101202, 5, "vo_empress_101201_004", 101201, "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ナナカ", 4, "", "vo_empress_101301_001", 49, "", 1, 101301, 5, "vo_empress_101301_001", 0, "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ナナカ", 4, "", "vo_empress_101301_002", 50, "", 1, 101301, 5, "vo_empress_101301_002", 0, "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ナナカ", 4, "", "vo_empress_101301_003", 51, "", 1, 101303, 5, "vo_empress_101301_003", 0, "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ナナカ", 4, "", "vo_empress_101301_004", 52, "", 1, 101302, 5, "vo_empress_101301_004", 101301, "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "カスミ", 4, "", "vo_empress_101401_001", 53, "", 1, 101401, 5, "vo_empress_101401_001", 0, "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "カスミ", 4, "", "vo_empress_101401_002", 54, "", 1, 101401, 5, "vo_empress_101401_002", 0, "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "カスミ", 4, "", "vo_empress_101401_003", 55, "", 1, 101403, 5, "vo_empress_101401_003", 0, "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "カスミ", 4, "", "vo_empress_101401_004", 56, "", 1, 101402, 5, "vo_empress_101401_004", 101401, "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミサト", 4, "", "vo_empress_101501_001", 57, "", 1, 101501, 5, "vo_empress_101501_001", 0, "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミサト", 4, "", "vo_empress_101501_002", 58, "", 1, 101501, 5, "vo_empress_101501_002", 0, "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ミサト", 4, "", "vo_empress_101501_003", 59, "", 1, 101501, 5, "vo_empress_101501_003", 0, "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ミサト", 4, "", "vo_empress_101501_004", 60, "", 1, 101502, 5, "vo_empress_101501_004", 101501, "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "スズナ", 4, "", "vo_empress_101601_001", 61, "", 1, 101601, 5, "vo_empress_101601_001", 0, "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "スズナ", 4, "", "vo_empress_101601_002", 62, "", 1, 101601, 5, "vo_empress_101601_002", 0, "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "スズナ", 4, "", "vo_empress_101601_003", 63, "", 1, 101601, 5, "vo_empress_101601_003", 0, "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "スズナ", 4, "", "vo_empress_101601_004", 64, "", 1, 101602, 5, "vo_empress_101601_004", 101601, "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "カオリ", 4, "", "vo_empress_101701_001", 65, "", 1, 101701, 5, "vo_empress_101701_001", 0, "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "カオリ", 4, "", "vo_empress_101701_002", 66, "", 1, 101701, 5, "vo_empress_101701_002", 0, "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "カオリ", 4, "", "vo_empress_101701_003", 67, "", 1, 101703, 5, "vo_empress_101701_003", 0, "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "カオリ", 4, "", "vo_empress_101701_004", 68, "", 1, 101702, 5, "vo_empress_101701_004", 101701, "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "イオ", 4, "", "vo_empress_101801_001", 69, "", 1, 101801, 5, "vo_empress_101801_001", 0, "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "イオ", 4, "", "vo_empress_101801_002", 70, "", 1, 101801, 5, "vo_empress_101801_002", 0, "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "イオ", 4, "", "vo_empress_101801_003", 71, "", 1, 101803, 5, "vo_empress_101801_003", 0, "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "イオ", 4, "", "vo_empress_101801_004", 72, "", 1, 101802, 5, "vo_empress_101801_004", 101801, "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミミ", 4, "", "vo_empress_102001_001", 73, "", 1, 102003, 5, "vo_empress_102001_001", 0, "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミミ", 4, "", "vo_empress_102001_002", 74, "", 1, 102003, 5, "vo_empress_102001_002", 0, "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ミミ", 4, "", "vo_empress_102001_003", 75, "", 1, 102003, 5, "vo_empress_102001_003", 0, "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ミミ", 4, "", "vo_empress_102001_004", 76, "", 1, 102002, 5, "vo_empress_102001_004", 102001, "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クルミ", 4, "", "vo_empress_102101_001", 77, "", 1, 102101, 5, "vo_empress_102101_001", 0, "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クルミ", 4, "", "vo_empress_102101_002", 78, "", 1, 102101, 5, "vo_empress_102101_002", 0, "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "クルミ", 4, "", "vo_empress_102101_003", 79, "", 1, 102101, 5, "vo_empress_102101_003", 0, "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "クルミ", 4, "", "vo_empress_102101_004", 80, "", 1, 102102, 5, "vo_empress_102101_004", 102101, "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ヨリ", 4, "", "vo_empress_102201_001", 81, "", 1, 102201, 5, "vo_empress_102201_001", 0, "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ヨリ", 4, "", "vo_empress_102201_002", 82, "", 1, 102201, 5, "vo_empress_102201_002", 0, "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ヨリ", 4, "", "vo_empress_102201_003", 83, "", 1, 102203, 5, "vo_empress_102201_003", 0, "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ヨリ", 4, "", "vo_empress_102201_004", 84, "", 1, 102202, 5, "vo_empress_102201_004", 102201, "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アヤネ", 4, "", "vo_empress_102301_001", 85, "", 1, 102301, 5, "vo_empress_102301_001", 0, "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アヤネ", 4, "", "vo_empress_102301_002", 86, "", 1, 102303, 5, "vo_empress_102301_002", 0, "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "アヤネ", 4, "", "vo_empress_102301_003", 87, "", 1, 102303, 5, "vo_empress_102301_003", 0, "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "アヤネ", 4, "", "vo_empress_102301_004", 88, "", 1, 102302, 5, "vo_empress_102301_004", 102301, "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "スズメ", 4, "", "vo_empress_102501_001", 89, "", 1, 102503, 5, "vo_empress_102501_001", 0, "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "スズメ", 4, "", "vo_empress_102501_002", 90, "", 1, 102503, 5, "vo_empress_102501_002", 0, "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "スズメ", 4, "", "vo_empress_102501_003", 91, "", 1, 102503, 5, "vo_empress_102501_003", 0, "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "スズメ", 4, "", "vo_empress_102501_004", 92, "", 1, 102502, 5, "vo_empress_102501_004", 102501, "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "リン", 4, "", "vo_empress_102601_001", 93, "", 1, 102603, 5, "vo_empress_102601_001", 0, "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "リン", 4, "", "vo_empress_102601_002", 94, "", 1, 102603, 5, "vo_empress_102601_002", 0, "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "リン", 4, "", "vo_empress_102601_003", 95, "", 1, 102603, 5, "vo_empress_102601_003", 0, "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "リン", 4, "", "vo_empress_102601_004", 96, "", 1, 102602, 5, "vo_empress_102601_004", 102601, "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "エリコ", 4, "", "vo_empress_102701_001", 97, "", 1, 102701, 5, "vo_empress_102701_001", 0, "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "エリコ", 4, "", "vo_empress_102701_002", 98, "", 1, 102701, 5, "vo_empress_102701_002", 0, "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "エリコ", 4, "", "vo_empress_102701_003", 99, "", 1, 102703, 5, "vo_empress_102701_003", 0, "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "エリコ", 4, "", "vo_empress_102701_004", 100, "", 1, 102702, 5, "vo_empress_102701_004", 102701, "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "サレン", 4, "", "vo_empress_102801_001", 101, "", 1, 102801, 5, "vo_empress_102801_001", 0, "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, "サレン", 4, 1, "vo_empress_102801_002", 102, 10000, 1, 102801, 3, "vo_empress_102801_002", 0, "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "サレン", 4, "", "vo_empress_102801_003", 103, "", 1, 102803, 5, "vo_empress_102801_003", 0, "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "サレン", 4, "", "vo_empress_102801_004", 104, "", 1, 102802, 5, "vo_empress_102801_004", 102801, "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ノゾミ", 4, "", "vo_empress_102901_001", 105, "", 1, 102903, 5, "vo_empress_102901_001", 0, "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ノゾミ", 4, "", "vo_empress_102901_002", 106, "", 1, 102903, 5, "vo_empress_102901_002", 0, "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ノゾミ", 4, "", "vo_empress_102901_003", 107, "", 1, 102903, 5, "vo_empress_102901_003", 0, "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ノゾミ", 4, "", "vo_empress_102901_004", 108, "", 1, 102901, 5, "vo_empress_102901_004", 102901, "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ニノン", 4, "", "vo_empress_103001_001", 109, "", 1, 103001, 5, "vo_empress_103001_001", 0, "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ニノン", 4, "", "vo_empress_103001_002", 110, "", 1, 103001, 5, "vo_empress_103001_002", 0, "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ニノン", 4, "", "vo_empress_103001_003", 111, "", 1, 103003, 5, "vo_empress_103001_003", 0, "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ニノン", 4, "", "vo_empress_103001_004", 112, "", 1, 103002, 5, "vo_empress_103001_004", 103001, "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "シノブ", 4, "", "vo_empress_103101_001", 113, "", 1, 103101, 5, "vo_empress_103101_001", 0, "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "シノブ", 4, "", "vo_empress_103101_002", 114, "", 1, 103101, 5, "vo_empress_103101_002", 0, "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "シノブ", 4, "", "vo_empress_103101_003", 115, "", 1, 103103, 5, "vo_empress_103101_003", 0, "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "シノブ", 4, "", "vo_empress_103101_004", 116, "", 1, 103101, 5, "vo_empress_103101_004", 103101, "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アキノ", 4, "", "vo_empress_103201_001", 117, "", 1, 103201, 5, "vo_empress_103201_001", 0, "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アキノ", 4, "", "vo_empress_103201_002", 118, "", 1, 103201, 5, "vo_empress_103201_002", 0, "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "アキノ", 4, "", "vo_empress_103201_003", 119, "", 1, 103203, 5, "vo_empress_103201_003", 0, "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "アキノ", 4, "", "vo_empress_103201_004", 120, "", 1, 103202, 5, "vo_empress_103201_004", 103201, "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "マヒル", 4, "", "vo_empress_103301_001", 121, "", 1, 103301, 5, "vo_empress_103301_001", 0, "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "マヒル", 4, "", "vo_empress_103301_002", 122, "", 1, 103301, 5, "vo_empress_103301_002", 0, "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "マヒル", 4, "", "vo_empress_103301_003", 123, "", 1, 103303, 5, "vo_empress_103301_003", 0, "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "マヒル", 4, "", "vo_empress_103301_004", 124, "", 1, 103302, 5, "vo_empress_103301_004", 103301, "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ユカリ", 4, "", "vo_empress_103401_001", 125, "", 1, 103401, 5, "vo_empress_103401_001", 0, "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ユカリ", 4, "", "vo_empress_103401_002", 126, "", 1, 103401, 5, "vo_empress_103401_002", 0, "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ユカリ", 4, "", "vo_empress_103401_003", 127, "", 1, 103403, 5, "vo_empress_103401_003", 0, "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ユカリ", 4, "", "vo_empress_103401_004", 128, "", 1, 103402, 5, "vo_empress_103401_004", 103401, "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "キョウカ", 4, "", "vo_empress_103601_001", 129, "", 1, 103603, 5, "vo_empress_103601_001", 0, "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "キョウカ", 4, "", "vo_empress_103601_002", 130, "", 1, 103603, 5, "vo_empress_103601_002", 0, "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "キョウカ", 4, "", "vo_empress_103601_003", 131, "", 1, 103601, 5, "vo_empress_103601_003", 0, "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "キョウカ", 4, "", "vo_empress_103601_004", 132, "", 1, 103602, 5, "vo_empress_103601_004", 103601, "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "トモ", 4, "", "vo_empress_103701_001", 133, "", 1, 103701, 5, "vo_empress_103701_001", 0, "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "トモ", 4, "", "vo_empress_103701_002", 134, "", 1, 103701, 5, "vo_empress_103701_002", 0, "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "トモ", 4, "", "vo_empress_103701_003", 135, "", 1, 103701, 5, "vo_empress_103701_003", 0, "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "トモ", 4, "", "vo_empress_103701_004", 136, "", 1, 103702, 5, "vo_empress_103701_004", 103701, "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "シオリ", 4, "", "vo_empress_103801_001", 137, "", 1, 103801, 5, "vo_empress_103801_001", 0, "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "シオリ", 4, "", "vo_empress_103801_002", 138, "", 1, 103801, 5, "vo_empress_103801_002", 0, "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "シオリ", 4, "", "vo_empress_103801_003", 139, "", 1, 103803, 5, "vo_empress_103801_003", 0, "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "シオリ", 4, "", "vo_empress_103801_004", 140, "", 1, 103802, 5, "vo_empress_103801_004", 103801, "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アオイ", 4, "", "vo_empress_104001_001", 141, "", 1, 104001, 5, "vo_empress_104001_001", 0, "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アオイ", 4, "", "vo_empress_104001_002", 142, "", 1, 104002, 5, "vo_empress_104001_002", 0, "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "アオイ", 4, "", "vo_empress_104001_003", 143, "", 1, 104003, 5, "vo_empress_104001_003", 0, "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "アオイ", 4, "", "vo_empress_104001_004", 144, "", 1, 104002, 5, "vo_empress_104001_004", 104001, "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "チカ", 4, "", "vo_empress_104201_001", 145, "", 1, 104203, 5, "vo_empress_104201_001", 0, "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "チカ", 4, "", "vo_empress_104201_002", 146, "", 1, 104201, 5, "vo_empress_104201_002", 0, "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "チカ", 4, "", "vo_empress_104201_003", 147, "", 1, 104203, 5, "vo_empress_104201_003", 0, "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "チカ", 4, "", "vo_empress_104201_004", 148, "", 1, 104201, 5, "vo_empress_104201_004", 104201, "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "マコト", 4, "", "vo_empress_104301_001", 149, "", 1, 104301, 5, "vo_empress_104301_001", 0, "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "マコト", 4, "", "vo_empress_104301_002", 150, "", 1, 104301, 5, "vo_empress_104301_002", 0, "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "マコト", 4, "", "vo_empress_104301_003", 151, "", 1, 104303, 5, "vo_empress_104301_003", 0, "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "マコト", 4, "", "vo_empress_104301_004", 152, "", 1, 104302, 5, "vo_empress_104301_004", 104301, "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "イリヤ", 4, "", "vo_empress_104401_001", 153, "", 1, 104401, 5, "vo_empress_104401_001", 0, "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "イリヤ", 4, "", "vo_empress_104401_002", 154, "", 1, 104401, 5, "vo_empress_104401_002", 0, "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "イリヤ", 4, "", "vo_empress_104401_003", 155, "", 1, 104401, 5, "vo_empress_104401_003", 0, "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "イリヤ", 4, "", "vo_empress_104401_004", 156, "", 1, 104401, 5, "vo_empress_104401_004", 104401, "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クウカ", 4, "", "vo_empress_104501_001", 157, "", 1, 104501, 5, "vo_empress_104501_001", 0, "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クウカ", 4, "", "vo_empress_104501_002", 158, "", 1, 104501, 5, "vo_empress_104501_002", 0, "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "クウカ", 4, "", "vo_empress_104501_003", 159, "", 1, 104503, 5, "vo_empress_104501_003", 0, "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "クウカ", 4, "", "vo_empress_104501_004", 160, "", 1, 104502, 5, "vo_empress_104501_004", 104501, "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "タマキ", 4, "", "vo_empress_104601_001", 161, "", 1, 104601, 5, "vo_empress_104601_001", 0, "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "タマキ", 4, "", "vo_empress_104601_002", 162, "", 1, 104601, 5, "vo_empress_104601_002", 0, "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "タマキ", 4, "", "vo_empress_104601_003", 163, "", 1, 104603, 5, "vo_empress_104601_003", 0, "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "タマキ", 4, "", "vo_empress_104601_004", 164, "", 1, 104602, 5, "vo_empress_104601_004", 104601, "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ジュン", 4, "", "vo_empress_104701_001", 165, "", 1, 104701, 5, "vo_empress_104701_001", 0, "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ジュン", 4, "", "vo_empress_104701_002", 166, "", 1, 104701, 5, "vo_empress_104701_002", 0, "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ジュン", 4, "", "vo_empress_104701_003", 167, "", 1, 104701, 5, "vo_empress_104701_003", 0, "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ジュン", 4, "", "vo_empress_104701_004", 168, "", 1, 104701, 5, "vo_empress_104701_004", 104701, "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミフユ", 4, "", "vo_empress_104801_001", 169, "", 1, 104801, 5, "vo_empress_104801_001", 0, "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミフユ", 4, "", "vo_empress_104801_002", 170, "", 1, 104801, 5, "vo_empress_104801_002", 0, "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ミフユ", 4, "", "vo_empress_104801_003", 171, "", 1, 104803, 5, "vo_empress_104801_003", 0, "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ミフユ", 4, "", "vo_empress_104801_004", 172, "", 1, 104802, 5, "vo_empress_104801_004", 104801, "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "シズル", 4, "", "vo_empress_104901_001", 173, "", 1, 104902, 5, "vo_empress_104901_001", 0, "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "シズル", 4, "", "vo_empress_104901_002", 174, "", 1, 104902, 5, "vo_empress_104901_002", 0, "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "シズル", 4, "", "vo_empress_104901_003", 175, "", 1, 104903, 5, "vo_empress_104901_003", 0, "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "シズル", 4, "", "vo_empress_104901_004", 176, "", 1, 104902, 5, "vo_empress_104901_004", 104901, "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミサキ", 4, "", "vo_empress_105001_001", 177, "", 1, 105001, 5, "vo_empress_105001_001", 0, "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミサキ", 4, "", "vo_empress_105001_002", 178, "", 1, 105001, 5, "vo_empress_105001_002", 0, "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ミサキ", 4, "", "vo_empress_105001_003", 179, "", 1, 105003, 5, "vo_empress_105001_003", 0, "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ミサキ", 4, "", "vo_empress_105001_004", 180, "", 1, 105002, 5, "vo_empress_105001_004", 105001, "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミツキ", 4, "", "vo_empress_105101_001", 181, "", 1, 105101, 5, "vo_empress_105101_001", 0, "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミツキ", 4, "", "vo_empress_105101_002", 182, "", 1, 105101, 5, "vo_empress_105101_002", 0, "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ミツキ", 4, "", "vo_empress_105101_003", 183, "", 1, 105101, 5, "vo_empress_105101_003", 0, "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ミツキ", 4, "", "vo_empress_105101_004", 184, "", 1, 105101, 5, "vo_empress_105101_004", 105101, "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "リマ", 4, "", "vo_empress_105201_001", 185, "", 1, 105201, 5, "vo_empress_105201_001", 0, "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, "リマ", 4, 1, "vo_empress_105201_002", 186, 10000, 1, 105201, 3, "vo_empress_105201_002", 0, "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "リマ", 4, "", "vo_empress_105201_003", 187, "", 1, 105201, 5, "vo_empress_105201_003", 0, "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "リマ", 4, "", "vo_empress_105201_004", 188, "", 1, 105202, 5, "vo_empress_105201_004", 105201, "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "モニカ", 4, "", "vo_empress_105301_001", 189, "", 1, 105303, 5, "vo_empress_105301_001", 0, "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "モニカ", 4, "", "vo_empress_105301_002", 190, "", 1, 105301, 5, "vo_empress_105301_002", 0, "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "モニカ", 4, "", "vo_empress_105301_003", 191, "", 1, 105301, 5, "vo_empress_105301_003", 0, "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "モニカ", 4, "", "vo_empress_105301_004", 192, "", 1, 105302, 5, "vo_empress_105301_004", 105301, "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ツムギ", 4, "", "vo_empress_105401_001", 193, "", 1, 105401, 5, "vo_empress_105401_001", 0, "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, "ツムギ", 4, 1, "vo_empress_105401_002", 194, 10000, 1, 105403, 3, "vo_empress_105401_002", 0, "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ツムギ", 4, "", "vo_empress_105401_003", 195, "", 1, 105403, 5, "vo_empress_105401_003", 0, "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ツムギ", 4, "", "vo_empress_105401_004", 196, "", 1, 105401, 5, "vo_empress_105401_004", 105401, "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アユミ", 4, "", "vo_empress_105501_001", 197, "", 1, 105503, 5, "vo_empress_105501_001", 0, "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アユミ", 4, "", "vo_empress_105501_002", 198, "", 1, 105501, 5, "vo_empress_105501_002", 0, "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "アユミ", 4, "", "vo_empress_105501_003", 199, "", 1, 105503, 5, "vo_empress_105501_003", 0, "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "アユミ", 4, "", "vo_empress_105501_004", 200, "", 1, 105502, 5, "vo_empress_105501_004", 105501, "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ルカ", 4, "", "vo_empress_105601_001", 201, "", 1, 105601, 5, "vo_empress_105601_001", 0, "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ルカ", 4, "", "vo_empress_105601_002", 202, "", 1, 105601, 5, "vo_empress_105601_002", 0, "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ルカ", 4, "", "vo_empress_105601_003", 203, "", 1, 105603, 5, "vo_empress_105601_003", 0, "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ルカ", 4, "", "vo_empress_105601_004", 204, "", 1, 105602, 5, "vo_empress_105601_004", 105601, "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ペコリーヌ", 4, "", "vo_empress_105801_001", 205, "", 1, 105803, 5, "vo_empress_105801_001", 0, "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4003, "ペコリーヌ", 4, 1, "vo_empress_105801_002", 206, 10000, 1, 105801, 3, "vo_empress_105801_002", 0, "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ペコリーヌ", 4, "", "vo_empress_105801_003", 207, "", 1, 105803, 5, "vo_empress_105801_003", 0, "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ペコリーヌ", 4, "", "vo_empress_105801_004", 208, "", 1, 105802, 5, "vo_empress_105801_004", 105801, "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "コッコロ", 4, "", "vo_empress_105901_001", 209, "", 1, 105903, 5, "vo_empress_105901_001", 0, "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "コッコロ", 4, "", "vo_empress_105901_002", 210, "", 1, 105905, 5, "vo_empress_105901_002", 0, "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "コッコロ", 4, "", "vo_empress_105901_003", 211, "", 1, 105903, 5, "vo_empress_105901_003", 0, "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "コッコロ", 4, "", "vo_empress_105901_004", 212, "", 1, 105902, 5, "vo_empress_105901_004", 105901, "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, "キャル", 4, 1, "vo_empress_106001_001", 213, 10000, 1, 106001, 3, "vo_empress_106001_001", 0, "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "キャル", 4, "", "vo_empress_106001_002", 214, "", 1, 106003, 5, "vo_empress_106001_002", 0, "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "キャル", 4, "", "vo_empress_106001_003", 215, "", 1, 106003, 5, "vo_empress_106001_003", 0, "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "キャル", 4, "", "vo_empress_106001_004", 216, "", 1, 106002, 5, "vo_empress_106001_004", 106001, "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ノウェム", 4, "", "vo_empress_106101_001", 217, "", 1, 106102, 5, "vo_empress_106101_001", 0, "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ノウェム", 4, "", "vo_empress_106101_002", 218, "", 1, 106101, 5, "vo_empress_106101_002", 0, "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ノウェム", 4, "", "vo_empress_106101_003", 219, "", 1, 106103, 5, "vo_empress_106101_003", 0, "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ノウェム", 4, "", "vo_empress_106101_004", 220, "", 1, 106102, 5, "vo_empress_106101_004", 106101, "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "シェフィ", 4, "", "vo_empress_106401_001", 221, "", 1, 106401, 5, "vo_empress_106401_001", 0, "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4004, "シェフィ", 4, 1, "vo_empress_106401_002", 222, 10000, 1, 106403, 3, "vo_empress_106401_002", 0, "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "シェフィ", 4, "", "vo_empress_106401_003", 223, "", 1, 106401, 5, "vo_empress_106401_003", 0, "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "シェフィ", 4, "", "vo_empress_106401_004", 224, "", 1, 106402, 5, "vo_empress_106401_004", 106401, "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "カヤ", 4, "", "vo_empress_106501_001", 225, "", 1, 106501, 5, "vo_empress_106501_001", 0, "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "カヤ", 4, "", "vo_empress_106501_002", 226, "", 1, 106501, 5, "vo_empress_106501_002", 0, "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "カヤ", 4, "", "vo_empress_106501_003", 227, "", 1, 106503, 5, "vo_empress_106501_003", 0, "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "カヤ", 4, "", "vo_empress_106501_004", 228, "", 1, 106501, 5, "vo_empress_106501_004", 106501, "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "イノリ", 4, "", "vo_empress_106601_001", 229, "", 1, 106603, 5, "vo_empress_106601_001", 0, "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "イノリ", 4, "", "vo_empress_106601_002", 230, "", 1, 106601, 5, "vo_empress_106601_002", 0, "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "イノリ", 4, "", "vo_empress_106601_003", 231, "", 1, 106603, 5, "vo_empress_106601_003", 0, "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "イノリ", 4, "", "vo_empress_106601_004", 232, "", 1, 106602, 5, "vo_empress_106601_004", 106601, "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ホマレ", 4, "", "vo_empress_106701_001", 233, "", 1, 106701, 5, "vo_empress_106701_001", 0, "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ホマレ", 4, "", "vo_empress_106701_002", 234, "", 1, 106701, 5, "vo_empress_106701_002", 0, "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ホマレ", 4, "", "vo_empress_106701_003", 235, "", 1, 106703, 5, "vo_empress_106701_003", 0, "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ホマレ", 4, "", "vo_empress_106701_004", 236, "", 1, 106702, 5, "vo_empress_106701_004", 106701, "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ラビリスタ", 4, "", "vo_empress_106801_001", 237, "", 1, 106802, 5, "vo_empress_106801_001", 0, "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, "ラビリスタ", 4, 1, "vo_empress_106801_002", 238, 10000, 1, 106801, 3, "vo_empress_106801_002", 0, "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ラビリスタ", 4, "", "vo_empress_106801_003", 239, "", 1, 106801, 5, "vo_empress_106801_003", 0, "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ラビリスタ", 4, "", "vo_empress_106801_004", 240, "", 1, 106802, 5, "vo_empress_106801_004", 106801, "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, "ネネカ", 4, 1, "vo_empress_107001_001", 241, 10000, 1, 107001, 3, "vo_empress_107001_001", 0, "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ネネカ", 4, "", "vo_empress_107001_002", 242, "", 1, 107001, 5, "vo_empress_107001_002", 0, "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ネネカ", 4, "", "vo_empress_107001_003", 243, "", 1, 107001, 5, "vo_empress_107001_003", 0, "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ネネカ", 4, "", "vo_empress_107001_004", 244, "", 1, 107002, 5, "vo_empress_107001_004", 107001, "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クリスティーナ", 4, "", "vo_empress_107101_001", 245, "", 1, 107101, 5, "vo_empress_107101_001", 0, "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, "クリスティーナ", 4, 1, "vo_empress_107101_002", 246, 10000, 1, 107101, 3, "vo_empress_107101_002", 0, "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "クリスティーナ", 4, "", "vo_empress_107101_003", 247, "", 1, 107103, 5, "vo_empress_107101_003", 0, "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "クリスティーナ", 4, "", "vo_empress_107101_004", 248, "", 1, 107102, 5, "vo_empress_107101_004", 107101, "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クロエ", 4, "", "vo_empress_110801_001", 249, "", 1, 110801, 5, "vo_empress_110801_001", 0, "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, "クロエ", 4, 1, "vo_empress_110801_002", 250, 10000, 1, 110801, 3, "vo_empress_110801_002", 0, "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "クロエ", 4, "", "vo_empress_110801_003", 251, "", 1, 110803, 5, "vo_empress_110801_003", 0, "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "クロエ", 4, "", "vo_empress_110801_004", 252, "", 1, 110802, 5, "vo_empress_110801_004", 110801, "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "チエル", 4, "", "vo_empress_110901_001", 253, "", 1, 110901, 5, "vo_empress_110901_001", 0, "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "チエル", 4, "", "vo_empress_110901_002", 254, "", 1, 110901, 5, "vo_empress_110901_002", 0, "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "チエル", 4, "", "vo_empress_110901_003", 255, "", 1, 110903, 5, "vo_empress_110901_003", 0, "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "チエル", 4, "", "vo_empress_110901_004", 256, "", 1, 110902, 5, "vo_empress_110901_004", 110901, "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ユニ", 4, "", "vo_empress_111001_001", 257, "", 1, 111001, 5, "vo_empress_111001_001", 0, "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ユニ", 4, "", "vo_empress_111001_002", 258, "", 1, 111001, 5, "vo_empress_111001_002", 0, "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ユニ", 4, "", "vo_empress_111001_003", 259, "", 1, 111003, 5, "vo_empress_111001_003", 0, "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ユニ", 4, "", "vo_empress_111001_004", 260, "", 1, 111002, 5, "vo_empress_111001_004", 111001, "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クレジッタ", 4, "", "vo_empress_118001_001", 261, "", 1, 118001, 5, "vo_empress_118001_001", 0, "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クレジッタ", 4, "", "vo_empress_118001_002", 262, "", 1, 118003, 5, "vo_empress_118001_002", 0, "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "クレジッタ", 4, "", "vo_empress_118001_003", 263, "", 1, 118003, 5, "vo_empress_118001_003", 0, "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "クレジッタ", 4, "", "vo_empress_118001_004", 264, "", 1, 118002, 5, "vo_empress_118001_004", 118001, "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ランファ", 4, "", "vo_empress_118101_001", 265, "", 1, 118101, 5, "vo_empress_118101_001", 0, "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ランファ", 4, "", "vo_empress_118101_002", 266, "", 1, 118101, 5, "vo_empress_118101_002", 0, "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ランファ", 4, "", "vo_empress_118101_003", 267, "", 1, 118103, 5, "vo_empress_118101_003", 0, "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ランファ", 4, "", "vo_empress_118101_004", 268, "", 1, 118102, 5, "vo_empress_118101_004", 118101, "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, "ミソラ", 4, 1, "vo_empress_118201_001", 269, 10000, 1, 118201, 3, "vo_empress_118201_001", 0, "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ミソラ", 4, "", "vo_empress_118201_002", 270, "", 1, 118201, 5, "vo_empress_118201_002", 0, "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ミソラ", 4, "", "vo_empress_118201_003", 271, "", 1, 118202, 5, "vo_empress_118201_003", 0, "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ミソラ", 4, "", "vo_empress_118201_004", 272, "", 1, 118202, 5, "vo_empress_118201_004", 118201, "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "カリン", 4, "", "vo_empress_118501_001", 273, "", 1, 118501, 5, "vo_empress_118501_001", 0, "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "カリン", 4, "", "vo_empress_118501_002", 274, "", 1, 118502, 5, "vo_empress_118501_002", 0, "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "カリン", 4, "", "vo_empress_118501_003", 275, "", 1, 118503, 5, "vo_empress_118501_003", 0, "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "カリン", 4, "", "vo_empress_118501_004", 276, "", 1, 118502, 5, "vo_empress_118501_004", 118501, "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ネビア", 4, "", "vo_empress_118601_001", 277, "", 1, 118601, 5, "vo_empress_118601_001", 0, "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ネビア", 4, "", "vo_empress_118601_002", 278, "", 1, 118601, 5, "vo_empress_118601_002", 0, "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ネビア", 4, "", "vo_empress_118601_003", 279, "", 1, 118603, 5, "vo_empress_118601_003", 0, "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ネビア", 4, "", "vo_empress_118601_004", 280, "", 1, 118602, 5, "vo_empress_118601_004", 118601, "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ヴァンピィ", 4, "", "vo_empress_122301_001", 281, "", 1, 122303, 5, "vo_empress_122301_001", 0, "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ヴァンピィ", 4, "", "vo_empress_122301_002", 282, "", 1, 122302, 5, "vo_empress_122301_002", 0, "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ヴァンピィ", 4, "", "vo_empress_122301_003", 283, "", 1, 122303, 5, "vo_empress_122301_003", 0, "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ヴァンピィ", 4, "", "vo_empress_122301_004", 284, "", 1, 122302, 5, "vo_empress_122301_004", 122301, "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アメス", 4, "", "vo_empress_123001_001", 285, "", 1, 123002, 5, "vo_empress_123001_001", 0, "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アメス", 4, "", "vo_empress_123001_002", 286, "", 1, 123001, 5, "vo_empress_123001_002", 0, "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "アメス", 4, "", "vo_empress_123001_003", 287, "", 1, 123003, 5, "vo_empress_123001_003", 0, "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "アメス", 4, "", "vo_empress_123001_004", 288, "", 1, 123002, 5, "vo_empress_123001_004", 123001, "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ネア", 4, "", "vo_empress_123301_001", 289, "", 1, 123301, 5, "vo_empress_123301_001", 0, "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ネア", 4, "", "vo_empress_123301_002", 290, "", 1, 123301, 5, "vo_empress_123301_002", 0, "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ネア", 4, "", "vo_empress_123301_003", 291, "", 1, 123303, 5, "vo_empress_123301_003", 0, "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ネア", 4, "", "vo_empress_123301_004", 292, "", 1, 123302, 5, "vo_empress_123301_004", 123301, "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クローチェ", 4, "", "vo_empress_126401_001", 293, "", 1, 126401, 5, "vo_empress_126401_001", 0, "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クローチェ", 4, "", "vo_empress_126401_002", 294, "", 1, 126401, 5, "vo_empress_126401_002", 0, "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "クローチェ", 4, "", "vo_empress_126401_003", 295, "", 1, 126403, 5, "vo_empress_126401_003", 0, "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "クローチェ", 4, "", "vo_empress_126401_004", 296, "", 1, 126402, 5, "vo_empress_126401_004", 126401, "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ライラエル", 4, "", "vo_empress_126501_001", 297, "", 1, 126501, 5, "vo_empress_126501_001", 0, "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, "ライラエル", 4, 1, "vo_empress_126501_002", 298, 10000, 1, 126506, 3, "vo_empress_126501_002", 0, "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ライラエル", 4, "", "vo_empress_126501_003", 299, "", 1, 126503, 5, "vo_empress_126501_003", 0, "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ライラエル", 4, "", "vo_empress_126501_004", 300, "", 1, 126502, 5, "vo_empress_126501_004", 126501, "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, "リンド", 4, 1, "vo_empress_127701_001", 301, 10000, 1, 127701, 3, "vo_empress_127701_001", 0, "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "リンド", 4, "", "vo_empress_127701_002", 302, "", 1, 127701, 5, "vo_empress_127701_002", 0, "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "リンド", 4, "", "vo_empress_127701_003", 303, "", 1, 127703, 5, "vo_empress_127701_003", 0, "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "リンド", 4, "", "vo_empress_127701_004", 304, "", 1, 127702, 5, "vo_empress_127701_004", 127701, "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ヴルム", 4, "", "vo_empress_127801_001", 305, "", 1, 127801, 5, "vo_empress_127801_001", 0, "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, "ヴルム", 4, 1, "vo_empress_127801_002", 306, 10000, 1, 127801, 3, "vo_empress_127801_002", 0, "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ヴルム", 4, "", "vo_empress_127801_003", 307, "", 1, 127803, 5, "vo_empress_127801_003", 0, "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ヴルム", 4, "", "vo_empress_127801_004", 308, "", 1, 127802, 5, "vo_empress_127801_004", 127801, "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, "エリス", 4, 1, "vo_empress_129001_001", 309, 10000, 1, 129001, 3, "vo_empress_129001_001", 0, "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "エリス", 4, "", "vo_empress_129001_002", 310, "", 1, 129001, 5, "vo_empress_129001_002", 0, "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "エリス", 4, "", "vo_empress_129001_003", 311, "", 1, 129003, 5, "vo_empress_129001_003", 0, "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "エリス", 4, "", "vo_empress_129001_004", 312, "", 1, 129002, 5, "vo_empress_129001_004", 129001, "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アネモネ", 4, "", "vo_empress_129601_001", 313, "", 1, 129601, 5, "vo_empress_129601_001", 0, "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アネモネ", 4, "", "vo_empress_129601_002", 314, "", 1, 129601, 5, "vo_empress_129601_002", 0, "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "アネモネ", 4, "", "vo_empress_129601_003", 315, "", 1, 129603, 5, "vo_empress_129601_003", 0, "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "アネモネ", 4, "", "vo_empress_129601_004", 316, "", 1, 129601, 5, "vo_empress_129601_004", 129601, "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ネフィ＝ネラ", 4, "", "vo_empress_129701_001", 317, "", 1, 129701, 5, "vo_empress_129701_001", 0, "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ネフィ＝ネラ", 4, "", "vo_empress_129701_002", 318, "", 1, 129701, 5, "vo_empress_129701_002", 0, "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ネフィ＝ネラ", 4, "", "vo_empress_129701_003", 319, "", 1, 129703, 5, "vo_empress_129701_003", 0, "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ネフィ＝ネラ", 4, "", "vo_empress_129701_004", 320, "", 1, 129702, 5, "vo_empress_129701_004", 129701, "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4003, "ヤマト", 4, 1, "vo_empress_130001_001", 321, 10000, 1, 130001, 3, "vo_empress_130001_001", 0, "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ヤマト", 4, "", "vo_empress_130001_002", 322, "", 1, 130001, 5, "vo_empress_130001_002", 0, "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ヤマト", 4, "", "vo_empress_130001_003", 323, "", 1, 130003, 5, "vo_empress_130001_003", 0, "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ヤマト", 4, "", "vo_empress_130001_004", 324, "", 1, 130002, 5, "vo_empress_130001_004", 130001, "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ワカナ", 4, "", "vo_empress_130101_001", 325, "", 1, 130101, 5, "vo_empress_130101_001", 0, "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ワカナ", 4, "", "vo_empress_130101_002", 326, "", 1, 130101, 5, "vo_empress_130101_002", 0, "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ワカナ", 4, "", "vo_empress_130101_003", 327, "", 1, 130103, 5, "vo_empress_130101_003", 0, "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ワカナ", 4, "", "vo_empress_130101_004", 328, "", 1, 130102, 5, "vo_empress_130101_004", 130101, "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "フブキ", 4, "", "vo_empress_130201_001", 329, "", 1, 130201, 5, "vo_empress_130201_001", 0, "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "フブキ", 4, "", "vo_empress_130201_002", 330, "", 1, 130201, 5, "vo_empress_130201_002", 0, "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "フブキ", 4, "", "vo_empress_130201_003", 331, "", 1, 130203, 5, "vo_empress_130201_003", 0, "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "フブキ", 4, "", "vo_empress_130201_004", 332, "", 1, 130202, 5, "vo_empress_130201_004", 130201, "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クルル", 4, "", "vo_empress_130901_001", 333, "", 1, 130901, 5, "vo_empress_130901_001", 0, "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クルル", 4, "", "vo_empress_130901_002", 334, "", 1, 130901, 5, "vo_empress_130901_002", 0, "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "クルル", 4, "", "vo_empress_130901_003", 335, "", 1, 130903, 5, "vo_empress_130901_003", 0, "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "クルル", 4, "", "vo_empress_130901_004", 336, "", 1, 130902, 5, "vo_empress_130901_004", 130901, "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ルイズマリー", 4, "", "vo_empress_132301_001", 337, "", 1, 132301, 5, "vo_empress_132301_001", 0, "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ルイズマリー", 4, "", "vo_empress_132301_002", 338, "", 1, 132301, 5, "vo_empress_132301_002", 0, "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ルイズマリー", 4, "", "vo_empress_132301_003", 339, "", 1, 132303, 5, "vo_empress_132301_003", 0, "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ルイズマリー", 4, "", "vo_empress_132301_004", 340, "", 1, 132302, 5, "vo_empress_132301_004", 132301, "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "イロハ", 4, "", "vo_empress_132401_001", 341, "", 1, 132401, 5, "vo_empress_132401_001", 0, "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "イロハ", 4, "", "vo_empress_132401_002", 342, "", 1, 132401, 5, "vo_empress_132401_002", 0, "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "イロハ", 4, "", "vo_empress_132401_003", 343, "", 1, 132401, 5, "vo_empress_132401_003", 0, "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "イロハ", 4, "", "vo_empress_132401_004", 344, "", 1, 132402, 5, "vo_empress_132401_004", 132401, "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ソノ", 4, "", "vo_empress_132501_001", 345, "", 1, 132501, 5, "vo_empress_132501_001", 0, "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ソノ", 4, "", "vo_empress_132501_002", 346, "", 1, 132501, 5, "vo_empress_132501_002", 0, "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ソノ", 4, "", "vo_empress_132501_003", 347, "", 1, 132503, 5, "vo_empress_132501_003", 0, "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ソノ", 4, "", "vo_empress_132501_004", 348, "", 1, 132502, 5, "vo_empress_132501_004", 132501, "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "グレイス", 4, "", "vo_empress_133001_001", 349, "", 1, 133001, 5, "vo_empress_133001_001", 0, "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4001, "グレイス", 4, 1, "vo_empress_133001_002", 350, 10000, 1, 133003, 3, "vo_empress_133001_002", 0, "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "グレイス", 4, "", "vo_empress_133001_003", 351, "", 1, 133003, 5, "vo_empress_133001_003", 0, "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "グレイス", 4, "", "vo_empress_133001_004", 352, "", 1, 133002, 5, "vo_empress_133001_004", 133001, "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ヴァイオレット", 4, "", "vo_empress_133101_001", 353, "", 1, 133101, 5, "vo_empress_133101_001", 0, "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4001, "ヴァイオレット", 4, 1, "vo_empress_133101_002", 354, 10000, 1, 133101, 3, "vo_empress_133101_002", 0, "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ヴァイオレット", 4, "", "vo_empress_133101_003", 355, "", 1, 133103, 5, "vo_empress_133101_003", 0, "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ヴァイオレット", 4, "", "vo_empress_133101_004", 356, "", 1, 133102, 5, "vo_empress_133101_004", 133101, "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "メドゥーサ", 4, "", "vo_empress_133601_001", 357, "", 1, 133601, 5, "vo_empress_133601_001", 0, "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "メドゥーサ", 4, "", "vo_empress_133601_002", 358, "", 1, 133601, 5, "vo_empress_133601_002", 0, "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "メドゥーサ", 4, "", "vo_empress_133601_003", 359, "", 1, 133603, 5, "vo_empress_133601_003", 0, "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "メドゥーサ", 4, "", "vo_empress_133601_004", 360, "", 1, 133602, 5, "vo_empress_133601_004", 133601, "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ホウオウ", 4, "", "vo_empress_134701_001", 361, "", 1, 134701, 5, "vo_empress_134701_001", 0, "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ホウオウ", 4, "", "vo_empress_134701_002", 362, "", 1, 134701, 5, "vo_empress_134701_002", 0, "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ホウオウ", 4, "", "vo_empress_134701_003", 363, "", 1, 134703, 5, "vo_empress_134701_003", 0, "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ホウオウ", 4, "", "vo_empress_134701_004", 364, "", 1, 134702, 5, "vo_empress_134701_004", 134701, "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "カノン", 4, "", "vo_empress_134901_001", 365, "", 1, 134901, 5, "vo_empress_134901_001", 0, "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "カノン", 4, "", "vo_empress_134901_002", 366, "", 1, 134901, 5, "vo_empress_134901_002", 0, "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "カノン", 4, "", "vo_empress_134901_003", 367, "", 1, 134903, 5, "vo_empress_134901_003", 0, "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "カノン", 4, "", "vo_empress_134901_004", 368, "", 1, 134902, 5, "vo_empress_134901_004", 134901, "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アイラ", 4, "", "vo_empress_135501_001", 369, "", 1, 135501, 5, "vo_empress_135501_001", 0, "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4005, "アイラ", 4, 1, "vo_empress_135501_002", 370, 10000, 1, 135501, 3, "vo_empress_135501_002", 0, "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "アイラ", 4, "", "vo_empress_135501_003", 371, "", 1, 135503, 5, "vo_empress_135501_003", 0, "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "アイラ", 4, "", "vo_empress_135501_004", 372, "", 1, 135502, 5, "vo_empress_135501_004", 135501, "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "シナツ", 4, "", "vo_empress_135601_001", 373, "", 1, 135601, 5, "vo_empress_135601_001", 0, "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "シナツ", 4, "", "vo_empress_135601_002", 374, "", 1, 135601, 5, "vo_empress_135601_002", 0, "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "シナツ", 4, "", "vo_empress_135601_003", 375, "", 1, 135603, 5, "vo_empress_135601_003", 0, "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "シナツ", 4, "", "vo_empress_135601_004", 376, "", 1, 135602, 5, "vo_empress_135601_004", 135601, "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4001, "ユキノ", 4, 1, "vo_empress_135801_001", 377, 10000, 1, 135801, 3, "vo_empress_135801_001", 0, "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ユキノ", 4, "", "vo_empress_135801_002", 378, "", 1, 135801, 5, "vo_empress_135801_002", 0, "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ユキノ", 4, "", "vo_empress_135801_003", 379, "", 1, 135803, 5, "vo_empress_135801_003", 0, "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ユキノ", 4, "", "vo_empress_135801_004", 380, "", 1, 135802, 5, "vo_empress_135801_004", 135801, "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4001, "サツキ", 4, 1, "vo_empress_135901_001", 381, 10000, 1, 135903, 3, "vo_empress_135901_001", 0, "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "サツキ", 4, "", "vo_empress_135901_002", 382, "", 1, 135901, 5, "vo_empress_135901_002", 0, "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "サツキ", 4, "", "vo_empress_135901_003", 383, "", 1, 135901, 5, "vo_empress_135901_003", 0, "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "サツキ", 4, "", "vo_empress_135901_004", 384, "", 1, 135902, 5, "vo_empress_135901_004", 135901, "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "アラクネ", 4, "", "vo_empress_136001_001", 385, "", 1, 136001, 5, "vo_empress_136001_001", 0, "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4003, "アラクネ", 4, 1, "vo_empress_136001_002", 386, 10000, 1, 136001, 3, "vo_empress_136001_002", 0, "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "アラクネ", 4, "", "vo_empress_136001_003", 387, "", 1, 136003, 5, "vo_empress_136001_003", 0, "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "アラクネ", 4, "", "vo_empress_136001_004", 388, "", 1, 136002, 5, "vo_empress_136001_004", 136001, "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ナーナ", 4, "", "vo_empress_136201_001", 389, "", 1, 136201, 5, "vo_empress_136201_001", 0, "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ナーナ", 4, "", "vo_empress_136201_002", 390, "", 1, 136201, 5, "vo_empress_136201_002", 0, "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ナーナ", 4, "", "vo_empress_136201_003", 391, "", 1, 136201, 5, "vo_empress_136201_003", 0, "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ナーナ", 4, "", "vo_empress_136201_004", 392, "", 1, 136202, 5, "vo_empress_136201_004", 136201, "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4001, "ルルィ", 4, 1, "vo_empress_136901_001", 393, 10000, 1, 136903, 3, "vo_empress_136901_001", 0, "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "ルルィ", 4, "", "vo_empress_136901_002", 394, "", 1, 136901, 5, "vo_empress_136901_002", 0, "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "ルルィ", 4, "", "vo_empress_136901_003", 395, "", 1, 136903, 5, "vo_empress_136901_003", 0, "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ルルィ", 4, "", "vo_empress_136901_004", 396, "", 1, 136902, 5, "vo_empress_136901_004", 136901, "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "リリ", 4, "", "vo_empress_139501_001", 397, "", 1, 139501, 5, "vo_empress_139501_001", 0, "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, "リリ", 4, 1, "vo_empress_139501_002", 398, 10000, 1, 139503, 3, "vo_empress_139501_002", 0, "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "リリ", 4, "", "vo_empress_139501_003", 399, "", 1, 139503, 5, "vo_empress_139501_003", 0, "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "リリ", 4, "", "vo_empress_139501_004", 400, "", 1, 139502, 5, "vo_empress_139501_004", 125801, "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "クリア", 4, "", "vo_empress_139601_001", 401, "", 1, 139603, 5, "vo_empress_139601_001", 0, "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (4002, "クリア", 4, 1, "vo_empress_139601_002", 402, 10000, 1, 139603, 3, "vo_empress_139601_002", 0, "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "クリア", 4, "", "vo_empress_139601_003", 403, "", 1, 139603, 5, "vo_empress_139601_003", 0, "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "クリア", 4, "", "vo_empress_139601_004", 404, "", 1, 139601, 5, "vo_empress_139601_004", 126001, "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "プレシア", 4, "", "vo_empress_139701_001", 405, "", 1, 139701, 5, "vo_empress_139701_001", 0, "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (1, "プレシア", 4, "", "vo_empress_139701_002", 406, "", 1, 139701, 5, "vo_empress_139701_002", 0, "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (2, "プレシア", 4, "", "vo_empress_139701_003", 407, "", 1, 139703, 5, "vo_empress_139701_003", 0, "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "プレシア", 4, "", "vo_empress_139701_004", 408, "", 1, 139702, 5, "vo_empress_139701_004", 126101, "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！");
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (3, "ティア", 4, "", "vo_empress_140301_004", 409, "", 1, 140301, 5, "vo_empress_140301_004", 140301, "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪");
